const NAVIGATION_PRESET_ENUMS = [
  'enum_navigation_items_preset',
  'enum_navigation_items_children_preset',
  'enum__navigation_v_version_items_preset',
  'enum__navigation_v_version_items_children_preset',
]

const MISSING_NAV_PRESET_VALUES = [
  '/goc-canh-bao',
  '/lich-kham-benh',
  '/lich-lam-viec',
]

export async function up({ client }) {
  // 1. Bổ sung các giá trị enum còn thiếu cho Navigation preset
  for (const enumName of NAVIGATION_PRESET_ENUMS) {
    for (const val of MISSING_NAV_PRESET_VALUES) {
      await client.query(`ALTER TYPE public."${enumName}" ADD VALUE IF NOT EXISTS '${val}';`)
    }
  }

  // 2. Làm sạch bản ghi mồ côi và đồng bộ đủ 587 khóa ngoại (CASCADE + SET NULL)
  for (const [childTable, childCol, parentTable, parentCol, fkName, onDelete] of ALL_SCHEMA_FKS) {
    const delCode = onDelete === 'CASCADE' ? 'c' : 'n'
    const cleanupSql =
      onDelete === 'CASCADE'
        ? `DELETE FROM public."${childTable}" c
           WHERE c."${childCol}" IS NOT NULL
             AND NOT EXISTS (
               SELECT 1 FROM public."${parentTable}" p WHERE p."${parentCol}" = c."${childCol}"
             );`
        : `UPDATE public."${childTable}" c
           SET "${childCol}" = NULL
           WHERE c."${childCol}" IS NOT NULL
             AND NOT EXISTS (
               SELECT 1 FROM public."${parentTable}" p WHERE p."${parentCol}" = c."${childCol}"
             );`

    await client.query(`
      DO $$ BEGIN
        IF EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = 'public' AND table_name = '${childTable}')
           AND EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = 'public' AND table_name = '${parentTable}') THEN
          ${cleanupSql}

          IF NOT EXISTS (
            SELECT 1
            FROM pg_constraint con
            JOIN pg_class c ON c.oid = con.conrelid
            JOIN pg_namespace n ON n.oid = c.relnamespace
            JOIN pg_class p ON p.oid = con.confrelid
            JOIN pg_attribute a ON a.attrelid = c.oid AND a.attnum = ANY(con.conkey)
            JOIN pg_attribute pa ON pa.attrelid = p.oid AND pa.attnum = ANY(con.confkey)
            WHERE con.contype = 'f'
              AND n.nspname = 'public'
              AND c.relname = '${childTable}'
              AND a.attname = '${childCol}'
              AND p.relname = '${parentTable}'
              AND pa.attname = '${parentCol}'
              AND con.confdeltype = '${delCode}'
          ) THEN
            ALTER TABLE public."${childTable}" DROP CONSTRAINT IF EXISTS "${fkName}";
            ALTER TABLE public."${childTable}"
              ADD CONSTRAINT "${fkName}"
              FOREIGN KEY ("${childCol}")
              REFERENCES public."${parentTable}"("${parentCol}")
              ON DELETE ${onDelete};
          END IF;
        END IF;
      END $$;
    `)
  }

  // 3. Đồng bộ lại toàn bộ SERIAL / sequence trên public schema
  const seqRes = await client.query(`
    SELECT
      t.table_name,
      c.column_name,
      pg_get_serial_sequence(format('public.%I', t.table_name), c.column_name) AS seq_name
    FROM information_schema.tables t
    JOIN information_schema.columns c
      ON c.table_schema = t.table_schema AND c.table_name = t.table_name
    WHERE t.table_schema = 'public'
      AND t.table_type = 'BASE TABLE'
      AND c.column_default LIKE 'nextval%'
    ORDER BY t.table_name;
  `)

  for (const row of seqRes.rows) {
    if (!row.seq_name) continue
    await client.query(`
      SELECT setval(
        $1,
        GREATEST(COALESCE((SELECT MAX("${row.column_name}") FROM public."${row.table_name}"), 0), 1),
        (SELECT COUNT(*) > 0 FROM public."${row.table_name}")
      );
    `, [row.seq_name])
  }
}

export async function verify({ client }) {
  const fkRes = await client.query(`
    SELECT count(*)::int AS cnt
    FROM pg_constraint
    WHERE connamespace = 'public'::regnamespace
      AND contype = 'f';
  `)
  if (Number(fkRes.rows[0]?.cnt || 0) < 580) {
    throw new Error(`Số lượng khóa ngoại trên database (${fkRes.rows[0]?.cnt}) chưa đạt mức chuẩn (>= 580).`)
  }

  const enumRes = await client.query(`
    SELECT e.enumlabel
    FROM pg_type t
    JOIN pg_enum e ON t.oid = e.enumtypid
    JOIN pg_catalog.pg_namespace n ON n.oid = t.typnamespace
    WHERE n.nspname = 'public'
      AND t.typname = 'enum_navigation_items_children_preset'
      AND e.enumlabel IN ('/goc-canh-bao', '/lich-kham-benh');
  `)
  if (enumRes.rowCount < 2) {
    throw new Error('Enum enum_navigation_items_children_preset vẫn thiếu giá trị /goc-canh-bao hoặc /lich-kham-benh.')
  }
}
